solutions.ts:
function countEvenDigitValues(nums: number[]): number {
  let count = 0;
  for (let x of nums) {
    let digits = 0;
    while (x > 0) {
      x = Math.floor(x / 10);
      digits++;
    }
    if (digits % 2 === 0) count++;
  }
  return count;
}

